float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

vec2 hash2(vec2 p) {
    p = vec2(dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)));
    return fract(sin(p) * 18.5453);
}

// Function to pick one of five colors based on a pseudorandom index
vec3 getTileColor(float index) {
    if (index < 0.2) return vec3(0.9, 0.3, 0.4); // Red
    if (index < 0.4) return vec3(0.3, 0.7, 0.9); // Blue
    if (index < 0.6) return vec3(0.9, 0.9, 0.3); // Yellow
    if (index < 0.8) return vec3(0.4, 0.9, 0.5); // Green
    return vec3(0.6, 0.4, 0.9);                  // Purple
}

vec3 getTileColor2(vec2 c) {
    return 0.5 + 0.5 * cos(c.y * 6. + vec3(0.0, 1.0, 2.0));
}

vec3 voronoi(in vec2 pos) {
    float scale = 3.;
    vec2 center = floor(pos / scale);
    vec2 centerOffset = fract(pos / scale);
    vec2 nearestCell = vec2(0.,0.);

    // x = distance, yz = seed
	vec3 m1 = vec3(8.0);
    vec3 m2 = vec3(8.0); // second-nearest
    // go though each grid square (8 neighbours + self) and determine min distance
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 cellOffset = vec2(float(i), float(j));
            vec2 cellCenter = center + cellOffset;
            vec2 o = hash2(cellCenter);
            vec2 r = cellOffset - centerOffset + o;
            //vec2 r = offset - f + (0.5 + 0.5 * sin(6. * o));
            float d = dot( r, r );
            if (d < m1.x) {
                m2 = m1;
                m1 = vec3( d, r );
                nearestCell = r;
            }
            else if (d < m2.x) {
                m2 = vec3( d, r );
            }
        }
    }

    vec2 v1 = m1.yz;
    vec2 v2 = m2.yz;
vec2 edgeVector = v2 - v1; // Vector between the two closest sites
vec2 edgeDirection = normalize(edgeVector); // Normalized direction
float distanceToBorder = abs(dot((v1 + v2) * 0.5, edgeDirection));

    // TODO: to combine with other shaders we'd actually need the center, not the (d,id)
    //return vec2( sqrt(m1.x), m1.y + m1.z );
    // return (u, v, d)
    return vec3(
        nearestCell.x,
        nearestCell.y,
        //sqrt(m1.x)
        //m1.y + m1.z
        distanceToBorder
    );
}

// TODO: we should probably round to the nearest multiple of 2 to avoid half tiles on the left
vec4 mosaic(vec2 pos) {
    // Convert to polar coordinates
    float radius = length(pos);
    float angle = atan(pos.y, pos.x);

    // Define the base tile size (distance between rings and tiles)
    float tileSize = 0.1;

    // Snap radius to the nearest ring center
    float ringIndex = floor(radius / tileSize);
    float snappedRadius = (ringIndex + 0.5) * tileSize;

    // Calculate the number of tiles in this ring based on circumference
    float tilesInRing = max(1.0, floor(2.0 * 3.14159265 * snappedRadius / tileSize));
    float tileAngle = 2.0 * 3.14159265 / tilesInRing;

    // Snap angle to the nearest tile center
    float snappedAngle = floor(angle / tileAngle) * tileAngle;

    // Convert snapped polar coordinates back to Cartesian
    vec2 tileCenter = vec2(cos(snappedAngle), sin(snappedAngle)) * snappedRadius;

    // Project back to UV space for squares
    vec2 gridUV = (pos - tileCenter) / tileSize;

    // Snap gridUV to the nearest square tile center
    gridUV = floor(gridUV) + 0.5;

    // Calculate the distance to the tile center (in square space)
    vec2 diff = (pos - tileCenter) / tileSize - gridUV;
    float squareDist = max(abs(diff.x), abs(diff.y)); // Distance for a square grid

    // Generate a pseudorandom index for this tile
    float tileHash = hash(ringIndex + floor(snappedAngle / tileAngle) * 57.0);
    vec3 tileColor = getTileColor(tileHash);

    // Add square borders
    float border = smoothstep(0.5, 0.52, squareDist);

    // TODO: instead return tile position, etc.?
    return vec4(tileColor * (1.0 - border), 1.0);
}

